// spec: specs/pwa-install-prompt.md (1.3) · кейс: .qa/tests/pwa-install-prompt/PWA-03.md
// seed: tests/seed.spec.ts (гость, без storageState, чистый localStorage) · проект iphone (WebKit, iPhone 13 Mini 375) · прод, только просмотр.
// Регресс #81a046 после фикса #631293: «אולי מאוחר יותר» → b4s_install_prompt_dismissed_at, окно не возвращается (прод — 5 дней).
// Снуз пишется только в localStorage окна теста (контекст одноразовый). Истечение 5 дней не проверяется.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, rpcResponse, installDialog, laterButton, chooseEssentialCookies, storageKey, DISMISSED_KEY, LOAD } from './pwa.helpers';

test('«אולי מאוחר יותר» на главной: окно закрыто, снуз записан, после перезагрузки окно не возвращается #631293 #81a046 @iphone @prod-safe', async ({ page, context }) => {
  await prepareReadOnly(context);
  await page.clock.install();
  const rpc = rpcResponse(page);
  await page.goto('/');
  await chooseEssentialCookies(page);
  await rpc;
  await page.clock.runFor(4_000);
  await expect(installDialog(page), 'окно установки появилось (контроль)').toBeVisible(LOAD);

  await laterButton(page).click();
  await expect(installDialog(page), 'окно закрыто').toBeHidden();
  const now = await page.evaluate(() => Date.now());
  const saved = Number(await storageKey(page, DISMISSED_KEY));
  expect(saved, `${DISMISSED_KEY} записан`).toBeGreaterThan(0);
  expect(Math.abs(now - saved), `${DISMISSED_KEY} = момент нажатия (мс)`).toBeLessThan(60_000);

  await page.reload();
  await expect(page.getByRole('button', { name: 'חיוניים בלבד' }), 'выбор cookie сохранён — баннера нет').toHaveCount(0);
  await page.clock.runFor(5_000);
  await expect(installDialog(page), 'после перезагрузки окна нет (5 с)').toBeHidden();
  await page.clock.runFor(15_000);
  await expect(installDialog(page), 'после перезагрузки окна нет (20 с)').toBeHidden();
  expect(Number(await storageKey(page, DISMISSED_KEY)), 'снуз не перезаписан').toBe(saved);
});
